def _to_seconds(value: str | None) -> int | None:
    if not value:
        return None
    parts = [int(x) for x in value.split(':')]
    if len(parts) == 2:
        return parts[0] * 60 + parts[1]
    if len(parts) == 3:
        return parts[0] * 3600 + parts[1] * 60 + parts[2]
    return None


def apply_final_resource_repairs(db: Session, *, commit: bool = True) -> dict[str, Any]:
    updated = 0
    missing = []
    changed = []
    now = datetime.now(timezone.utc).isoformat()
    for topic_slug, spec in FINAL_RESOURCE_REPAIRS.items():
        row = db.query(CurriculumResource).filter(CurriculumResource.slug == f"{topic_slug}-primary").first()
        if not row:
            # Some generated resources use the topic slug directly (notably DSA).
            row = db.query(CurriculumResource).filter(CurriculumResource.slug == topic_slug).first()
        if not row:
            missing.append(topic_slug)
            continue
        before = {
            "title": row.title, "url": row.url, "provider": row.provider,
            "section": row.section, "role": row.role, "resource_type": row.resource_type,
        }
        row.title = spec["title"]
        row.url = spec["url"]
        row.provider = spec["provider"]
        row.resource_type = spec["rtype"]
        row.role = spec.get("role", "PRIMARY")
        row.section = spec.get("section")
        row.lecture = spec.get("lecture")
        row.video_id = metadata_from_spec(url=spec["url"], resource_type=spec["rtype"], role=row.role, section=spec.get("section"), lecture=spec.get("lecture"))["video_id"]
        row.estimated_minutes = int(spec["mins"])
        row.estimate_confidence = "HIGH" if spec.get("start") and spec.get("end") else "MEDIUM"
        row.estimate_method = "VIDEO_TIMESTAMP" if spec.get("start") and spec.get("end") else "RESEARCHED_SECTION_ESTIMATE"
        row.boundary_type = "VIDEO_TIMESTAMP" if spec.get("start") and spec.get("end") else ("ARTICLE_SECTION" if spec.get("section") else "FULL_SINGLE_PAGE")
        row.start_boundary = spec.get("start") or spec.get("section")
        row.end_boundary = spec.get("end") or spec.get("section")
        row.start_timestamp = _to_seconds(spec.get("start"))
        row.end_timestamp = _to_seconds(spec.get("end"))
        row.exactness = "EXACT"
        row.learner_visible = True
        row.visibility_class = "LEARNER"
        row.notes = spec.get("note")
        row.verification_status = "NEEDS_REVIEW"
        row.verification_evidence = json.dumps({
            "verification_method": "FINAL_RESOURCE_RESEARCH_2026_08_26",
            "researched_at": now,
            "note": "Resource selected from live web research; independent lockdown verifier must re-check live page before READY promotion.",
            "decision_note": spec.get("note"),
        }, ensure_ascii=False)
        changed.append({"topic_slug": topic_slug, "before": before, "after": {"title": row.title, "url": row.url, "provider": row.provider, "section": row.section}})
        updated += 1

    if commit:
        db.commit()
    return {"updated": updated, "missing": missing, "changed": changed}
